import torch

from task import input_t, output_t


_MIXED_PRECISION_MIN_N = 4096


def _blocked_cholesky(data: torch.Tensor) -> torch.Tensor:
    """Right-looking blocked Cholesky with TF32 tensor-core updates."""
    out = data.clone()
    n = out.shape[-1]
    block = 8192 if out.shape[0] == 1 else 1024

    # The panel factorization and triangular solve remain FP32.  Only the
    # level-3 trailing update is permitted to use TF32 tensor-core products.
    torch.backends.cuda.matmul.allow_tf32 = True
    for k in range(0, n, block):
        stop = min(k + block, n)
        diagonal = out[:, k:stop, k:stop]
        factor = torch.linalg.cholesky_ex(diagonal, check_errors=False).L
        diagonal.copy_(factor)

        if stop == n:
            continue

        panel = out[:, stop:, k:stop]
        solved = torch.linalg.solve_triangular(
            factor,
            panel.transpose(-2, -1),
            upper=False,
        ).transpose(-2, -1)
        panel.copy_(solved)

        trailing = out[:, stop:, stop:]
        torch.baddbmm(
            trailing,
            solved,
            solved.transpose(-2, -1),
            beta=1.0,
            alpha=-1.0,
            out=trailing,
        )

    return out.tril_()


def custom_kernel(data: input_t) -> output_t:
    if data.shape[-1] >= _MIXED_PRECISION_MIN_N:
        return _blocked_cholesky(data)
    return torch.linalg.cholesky_ex(data, check_errors=False).L
