#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cublas_v2.h>

void tf32_syrk_(torch::Tensor trailing, torch::Tensor panel) {
    TORCH_CHECK(trailing.is_cuda() && panel.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(trailing.scalar_type() == torch::kFloat32, "FP32 trailing matrix required");
    TORCH_CHECK(panel.scalar_type() == torch::kFloat32, "FP32 panel required");
    TORCH_CHECK(trailing.dim() == 3 && panel.dim() == 3, "batched matrices required");

    const int batch = static_cast<int>(panel.size(0));
    const int n = static_cast<int>(panel.size(1));
    const int k = static_cast<int>(panel.size(2));
    const int lda = static_cast<int>(panel.stride(1));
    const int ldc = static_cast<int>(trailing.stride(1));
    const int64_t panel_batch_stride = panel.stride(0);
    const int64_t trailing_batch_stride = trailing.stride(0);
    const float alpha = -1.0f;
    const float beta = 1.0f;

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    cublasMath_t old_math;
    TORCH_CHECK(cublasGetMathMode(handle, &old_math) == CUBLAS_STATUS_SUCCESS,
                "cublasGetMathMode failed");
    TORCH_CHECK(cublasSetMathMode(handle, CUBLAS_TF32_TENSOR_OP_MATH) == CUBLAS_STATUS_SUCCESS,
                "cublasSetMathMode failed");

    const float* panel_ptr = panel.data_ptr<float>();
    float* trailing_ptr = trailing.data_ptr<float>();
    for (int b = 0; b < batch; ++b) {
        // Row-major lower C is column-major upper C.  Likewise, the row-major
        // n-by-k panel is a column-major k-by-n operand, so op(A)^T A is L L^T.
        const cublasStatus_t status = cublasSsyrk(
            handle,
            CUBLAS_FILL_MODE_UPPER,
            CUBLAS_OP_T,
            n,
            k,
            &alpha,
            panel_ptr + b * panel_batch_stride,
            lda,
            &beta,
            trailing_ptr + b * trailing_batch_stride,
            ldc);
        TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasSsyrk failed");
    }
    TORCH_CHECK(cublasSetMathMode(handle, old_math) == CUBLAS_STATUS_SUCCESS,
                "failed to restore cuBLAS math mode");
}

